class Solution {
public:
    int minSwaps(vector<int>& nums) {
        int k = 0;
        for (int x : nums) k += x;
        if (k <= 1) return 0;
        int n = nums.size();
        int curr = 0;
        for (int i = 0; i < k; i++) curr += nums[i];
        int maxOnes = curr;
        for (int i = 0; i < n; i++) {
            curr += nums[(i + k) % n] - nums[i];
            if (curr > maxOnes) maxOnes = curr;
        }
        return k - maxOnes;
    }
};

