var minSwaps = function(nums) {
    const k = nums.reduce((a, b) => a + b, 0);
    if (k <= 1) return 0;
    const n = nums.length;
    let curr = 0;
    for (let i = 0; i < k; i++) curr += nums[i];
    let maxOnes = curr;
    for (let i = 0; i < n; i++) {
        curr += nums[(i + k) % n] - nums[i];
        if (curr > maxOnes) maxOnes = curr;
    }
    return k - maxOnes;
};
